public async Task<byte[]> RasterBatchAsync(IReadOnlyList<Stream> pages, CancellationToken cancellationToken)
{
    var encoded = new byte[pages.Count][];
    await Parallel.ForEachAsync(
        Enumerable.Range(0, pages.Count),
        new ParallelOptions { MaxDegreeOfParallelism = 4, CancellationToken = cancellationToken },
        async (index, token) =>
        {
            encoded[index] = await RasterOneCpuBoundAsync(pages[index], token);
        });
    return Combine(encoded);
}

public IEnumerable<int> ScoreRows(IEnumerable<int> raw) =>
    raw.AsParallel().WithDegreeOfParallelism(4).Select(static n => n * 2).ToList();
